export const clean = value => String(value ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9\s]/g,' ').replace(/\s+/g,' ').trim();
const stop = new Set('como puedo quiero necesito necesita saber para de del la el los las un una unos unas y o en al a que cual cuales es se por con sobre desde hasta hacia importar improtar importacion importaciones exportar exprotar exportacion exportaciones comprar traer vender producto productos requisitos pasos arancel arancelario clasificacion colombia colombiano colombianos china estados unidos usa mexico espana peru ecuador'.split(' '));
const legal = /\b(decreto|resolucion|ley|circular|doctrina|sentencia|concepto|normograma)\b/;
const topics = new Set(['arancel','origen','valoracion','anticipada','declaracion','rut','oea','aduana','aduanas','tributos','impuestos','contingencia','trafico postal','envios urgentes','zona franca','zonas francas','normativa','servicios','importar','exportar']);
const words = value => clean(value).split(' ').filter(x=>x && !stop.has(x));
function forms(word){const f=[word];if(word.length>4&&word.endsWith('s'))f.push(word.slice(0,-1));if(word.length>5&&word.endsWith('es'))f.push(word.slice(0,-2));if(word.endsWith('ces'))f.push(word.slice(0,-3)+'z');return f;}
function wordMatch(a,b){return forms(a).some(x=>forms(b).includes(x));}
const matches = (query,tokens) => query.every(t=>tokens.some(w=>wordMatch(t,w)));
function near(a,b){if(Math.abs(a.length-b.length)>1)return false;let i=0,j=0,edits=0;while(i<a.length&&j<b.length){if(a[i]===b[j]){i++;j++;continue;}if(++edits>1)return false;if(a.length>=b.length)i++;if(b.length>=a.length)j++;}return edits+(a.length-i)+(b.length-j)<=1;}

export function createProductSearch(data){
  const byCode=new Map([...data.chapters.filter(r=>!r.reserved),...data.headings,...data.subheadings].map(r=>[r.code,r]));
  const entries=[...data.headings,...data.subheadings].map(r=>({...r,own:words(r.title),context:words([r.title,byCode.get(r.code.slice(0,4))?.title].join(' '))}));
  function candidate(code){const r=byCode.get(code);if(!r)return null;return {code:r.code,title:r.title,chapter:code.slice(0,2),chapterTitle:byCode.get(code.slice(0,2))?.title,heading:code.length===6?byCode.get(code.slice(0,4))?.title:''};}
  function resultProfile(p,query,corrected=false){return {...p,query,kind:'profile',corrected,candidates:p.codes.map(candidate).filter(Boolean),total:p.codes.length};}
  function search(query){
    const raw=clean(query),tokens=words(query),str=tokens.join(' ');
    if(!raw||legal.test(raw)||topics.has(raw))return null;
    const numeric=String(query).trim().replace(/[.\s]/g,'').replace(/^(?:capitulo|partida|subpartida)\s*/i,'');
    const numbered=clean(query).match(/^(?:capitulo|partida|subpartida)\s+(\d{2,6})$/);
    const code=numbered?.[1]||numeric;
    if(/^\d+$/.test(code))return byCode.has(code)?{kind:'index',query,name:byCode.get(code).title,candidates:[candidate(code)],total:1,detail:'Contrasta la descripción, las notas de sección y de capítulo y las características de la mercancía.'}:null;
    if(!tokens.length)return null;
    // Require the complete product phrase: never discard an unknown accessory or material.
    const p=profiles.find(p=>p.aliases.some(a=>{const w=words(a);return w.length===tokens.length&&matches(tokens,w)&&matches(w,tokens);}));
    if(p)return resultProfile(p,query);
    const found=entries.filter(r=>matches(tokens,r.context)).map(r=>({...r,score:(matches(tokens,r.own)?100+60*tokens.length/Math.max(r.own.length,1):0)+(r.code.length===4?18:0)-Math.min(r.title.length/120,8)})).sort((a,b)=>b.score-a.score||a.code.localeCompare(b.code));
    if(found.length){
      // Prefer matched headings; show a subheading when only that specific description matches.
      const displayed=[];
      for(const r of found){if(displayed.some(x=>x.code.length===4&&r.code.startsWith(x.code)))continue;displayed.push(r);if(displayed.length===6)break;}
      return {kind:'index',query,name:query,candidates:displayed.map(r=>candidate(r.code)),total:found.length,intro:'Estas descripciones del índice arancelario coinciden con tu búsqueda. Úsalas para revisar la clasificación según las características del producto.',detail:'Reúne composición, uso, proceso de fabricación y presentación. Revisa las notas legales antes de elegir una subpartida.'};
    }
    // Corrections are suggestions only; the user must choose before seeing a tariff candidate.
    const suggestion=tokens.length===1&&tokens[0].length>=5?profiles.find(p=>p.aliases.some(a=>!a.includes(' ')&&near(str,clean(a)))):null;
    return {kind:'unknown',query,name:query,candidates:[],total:0,suggestion:suggestion?.name,suggestedQuery:suggestion?.aliases[0],intro:'Aún no ubicamos una descripción arancelaria con ese nombre. Prueba el nombre técnico, el material o el uso del producto; también puedes consultar el índice alfabético de la DIAN.',detail:'Añade el material, la función, el estado y la presentación. Por ejemplo: «camisetas de algodón» o «café tostado».'};
  }
  return {search,metadata:data.metadata,counts:{chapters:data.chapters.filter(r=>!r.reserved).length,headings:data.headings.length,subheadings:data.subheadings.length}};
}
